import numpy as np
from solver import Solver
s=Solver()
for dtype in [np.float64,np.float32,np.int64]:
 for n in [0,1,3,10]:
  a=np.arange(n,dtype=dtype)+1
  b=np.arange(n,dtype=dtype)+4
  r=s.solve((a,b))
  ref=np.outer(a,b)
  assert r.shape==ref.shape and np.allclose(r,ref), (dtype,n,r,ref)
print('ok')
